//! Dispatch wrapper for tile grid canvas messages.
//!
//! This module exists so the `define_update_dispatch!` macro can route
//! `EditorMessage::TileGridCanvas` to a `handle` function without colliding
//! with the standard `handle` generated by `define_standard_editor!` for
//! `StandardEditorMessage<TileGrid>`.

use crate::editors::tile_grid::{self, TileGridCanvasMessage};
use crate::message::Message;
use iced::Task;

pub fn handle(msg: TileGridCanvasMessage, app: &mut crate::app::App) -> Task<Message> {
    tile_grid::handle_canvas_message(msg, app)
}
